<?php
namespace App\Livewire\Verification;
use App\Domain\Documents\Services\AuthorizedDocumentQuery;use App\Domain\Verification\Enums\VerificationStage;use App\Domain\Verification\Services\VerificationWorkflow;use App\Models\DocumentVerification;use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithPagination;
#[Layout('layouts.app')]
class VerificationQueue extends Component{use WithPagination;public string $stage='QUALITY_CHECK',$status='PENDING';public function mount():void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'documents.verify'),403);}public function claim(int $id,VerificationWorkflow $workflow):void{$v=DocumentVerification::findOrFail($id);$workflow->assign($v,auth()->id(),auth()->id());}public function render(AuthorizedDocumentQuery $authorized){$permitted=$authorized->for(auth()->user())->select('documents.id');$rows=DocumentVerification::with(['document.documentType','document.district','document.revenueCircle','version'])->whereIn('document_id',$permitted)->where('stage',$this->stage)->when($this->status,fn($q)=>$q->where('status',$this->status))->where(function($q){$q->whereNull('assigned_to')->orWhere('assigned_to',auth()->id());})->orderBy('created_at')->paginate(25);return view('livewire.verification.verification-queue',['rows'=>$rows]);}}
